import pytest
from target import age_in_years


def test_exact_birthday_years_later():
    # Same month/day, year has fully advanced -> age equals year difference
    assert age_in_years(2000, 5, 15, 2020, 5, 15) == 20


def test_day_before_birthday():
    # One day short of the birthday -> age is one less than year difference
    assert age_in_years(2000, 5, 15, 2020, 5, 14) == 19


def test_day_after_birthday():
    # One day past the birthday -> full age reached
    assert age_in_years(2000, 5, 15, 2020, 5, 16) == 20


def test_born_today_zero_age():
    # Birth date equals "on" date -> age is 0
    assert age_in_years(2000, 1, 1, 2000, 1, 1) == 0


def test_full_year_elapsed_exact_date():
    assert age_in_years(2000, 12, 31, 2001, 12, 31) == 1


def test_one_day_short_of_full_year():
    assert age_in_years(2000, 12, 31, 2001, 12, 30) == 0


def test_leap_day_birthday_not_yet_reached():
    # Born on leap day; in a non-leap year, day before Feb 28/Mar 1 boundary
    # month matches (2 == 2) but day 28 < 29 -> birthday not yet reached
    assert age_in_years(2000, 2, 29, 2001, 2, 28) == 0


def test_leap_day_birthday_reached_after_february():
    # After February in a non-leap year, birthday considered passed
    assert age_in_years(2000, 2, 29, 2001, 3, 1) == 1


def test_same_year_same_day_zero_age():
    assert age_in_years(2000, 6, 15, 2000, 6, 15) == 0


def test_month_after_birth_month_increments_age():
    # Current month greater than birth month -> birthday has passed
    assert age_in_years(2000, 3, 10, 2020, 4, 1) == 20


def test_month_before_birth_month_no_increment():
    # Current month less than birth month -> birthday not yet reached
    assert age_in_years(2000, 3, 10, 2020, 2, 1) == 19


def test_large_age_span():
    assert age_in_years(1900, 1, 1, 2000, 1, 1) == 100


def test_month_same_day_after_birth_day():
    # Same month, day already past birth day -> birthday considered passed
    assert age_in_years(2005, 7, 4, 2025, 7, 10) == 20


def test_month_same_day_before_birth_day():
    # Same month, day before birth day -> birthday not yet reached
    assert age_in_years(2005, 7, 20, 2025, 7, 10) == 19

import pytest
from target import binary_search


def test_empty_list_returns_not_found():
    assert binary_search([], 5) == -1


def test_single_element_found():
    assert binary_search([5], 5) == 0


def test_single_element_not_found_smaller():
    assert binary_search([5], 3) == -1


def test_single_element_not_found_larger():
    assert binary_search([5], 7) == -1


def test_two_elements_find_first():
    assert binary_search([1, 3], 1) == 0


def test_two_elements_find_second():
    assert binary_search([1, 3], 3) == 1


def test_two_elements_not_found_between():
    assert binary_search([1, 3], 2) == -1


def test_first_element_of_larger_list():
    items = [1, 2, 3, 4, 5, 6, 7]
    assert binary_search(items, 1) == 0


def test_last_element_of_larger_list():
    items = [1, 2, 3, 4, 5, 6, 7]
    assert binary_search(items, 7) == 6


def test_middle_element_of_larger_list():
    items = [1, 2, 3, 4, 5, 6, 7]
    assert binary_search(items, 4) == 3


def test_element_just_below_range():
    items = [10, 20, 30, 40, 50]
    assert binary_search(items, 9) == -1


def test_element_just_above_range():
    items = [10, 20, 30, 40, 50]
    assert binary_search(items, 51) == -1


def test_target_between_two_middle_elements():
    items = [10, 20, 30, 40, 50]
    assert binary_search(items, 25) == -1


def test_even_length_list_found_left_mid():
    items = [1, 2, 3, 4, 5, 6]
    assert binary_search(items, 3) == 2


def test_even_length_list_found_right_mid():
    items = [1, 2, 3, 4, 5, 6]
    assert binary_search(items, 4) == 3


def test_duplicates_present_returns_valid_index():
    items = [1, 2, 2, 2, 3, 4]
    idx = binary_search(items, 2)
    assert idx in (1, 2, 3)
    assert items[idx] == 2


def test_negative_numbers_found():
    items = [-10, -5, -1, 0, 3, 8]
    assert binary_search(items, -5) == 1


def test_negative_numbers_not_found():
    items = [-10, -5, -1, 0, 3, 8]
    assert binary_search(items, -6) == -1


def test_large_sorted_list_boundaries():
    items = list(range(0, 1000, 2))  # even numbers 0..998
    assert binary_search(items, 0) == 0
    assert binary_search(items, 998) == 499
    assert binary_search(items, 999) == -1


def test_target_less_than_all_elements():
    items = [100, 200, 300]
    assert binary_search(items, 1) == -1


def test_target_greater_than_all_elements():
    items = [100, 200, 300]
    assert binary_search(items, 999) == -1

import math
import pytest

from target import ceil_div


def test_exact_division():
    assert ceil_div(10, 2) == 5


def test_exact_division_larger():
    assert ceil_div(9, 3) == 3


def test_division_with_remainder_rounds_up():
    assert ceil_div(10, 3) == 4


def test_division_with_remainder_rounds_up_2():
    assert ceil_div(8, 3) == 3


def test_numerator_zero():
    assert ceil_div(0, 5) == 0


def test_numerator_smaller_than_denominator():
    assert ceil_div(1, 5) == 1


def test_numerator_one_less_than_multiple():
    assert ceil_div(9, 4) == 3


def test_numerator_equals_denominator():
    assert ceil_div(7, 7) == 1


def test_denominator_one():
    assert ceil_div(7, 1) == 7


def test_remainder_of_one():
    assert ceil_div(11, 10) == 2


def test_boundary_just_above_multiple():
    assert ceil_div(21, 5) == 5


def test_boundary_exact_multiple_large():
    assert ceil_div(100, 25) == 4


def test_large_numbers():
    assert ceil_div(1_000_000_001, 1_000_000_000) == 2


def test_negative_numerator_positive_denominator():
    # ceil(-7 / 2) = ceil(-3.5) = -3
    assert ceil_div(-7, 2) == -3


def test_positive_numerator_negative_denominator():
    # ceil(7 / -2) = ceil(-3.5) = -3
    assert ceil_div(7, -2) == -3


def test_negative_numerator_and_denominator():
    # ceil(-7 / -2) = ceil(3.5) = 4
    assert ceil_div(-7, -2) == 4


def test_zero_denominator_raises():
    with pytest.raises(ZeroDivisionError):
        ceil_div(5, 0)

import pytest
from target import count_multiples_in_range


def test_basic_range_multiples_of_2():
    # 2,4,6,8,10 -> 5 multiples
    assert count_multiples_in_range(1, 10, 2) == 5


def test_basic_range_multiples_of_3():
    # 3,6,9 -> 3 multiples
    assert count_multiples_in_range(1, 10, 3) == 3


def test_start_equals_end_is_multiple():
    assert count_multiples_in_range(5, 5, 5) == 1


def test_start_equals_end_not_multiple():
    assert count_multiples_in_range(5, 5, 3) == 0


def test_zero_start_and_end_with_divisor_one():
    assert count_multiples_in_range(0, 0, 1) == 1


def test_negative_and_positive_range():
    # -10,-5,0,5,10 -> 5 multiples
    assert count_multiples_in_range(-10, 10, 5) == 5


def test_fully_negative_range():
    # -20,-15,-10,-5 -> 4 multiples
    assert count_multiples_in_range(-20, -1, 5) == 4


def test_single_element_range_multiple_of_one():
    assert count_multiples_in_range(1, 1, 1) == 1


def test_divisor_one_counts_every_number():
    assert count_multiples_in_range(1, 10, 1) == 10


def test_even_start_and_end_multiples_of_two():
    # 2,4,6,8,10 -> 5 multiples
    assert count_multiples_in_range(2, 10, 2) == 5


def test_no_multiples_when_divisor_larger_than_range():
    assert count_multiples_in_range(1, 5, 10) == 0


def test_invalid_range_start_greater_than_end():
    assert count_multiples_in_range(10, 1, 2) == 0


def test_large_range_multiples_of_seven():
    # floor(1000000/7) - floor(0/7) = 142857 - 0
    assert count_multiples_in_range(1, 1000000, 7) == 142857

import pytest
from target import day_of_year


def test_january_first():
    assert day_of_year(2023, 1, 1) == 1


def test_january_last_day():
    assert day_of_year(2023, 1, 31) == 31


def test_february_first_non_leap():
    assert day_of_year(2023, 2, 1) == 32


def test_february_last_day_non_leap():
    assert day_of_year(2023, 2, 28) == 59


def test_march_first_non_leap():
    assert day_of_year(2023, 3, 1) == 60


def test_december_31_non_leap_year():
    assert day_of_year(2023, 12, 31) == 365


def test_february_29_leap_year():
    assert day_of_year(2024, 2, 29) == 60


def test_march_first_leap_year():
    assert day_of_year(2024, 3, 1) == 61


def test_december_31_leap_year():
    assert day_of_year(2024, 12, 31) == 366


def test_century_year_not_divisible_by_400_not_leap():
    # 1900 is not a leap year (divisible by 100 but not 400)
    assert day_of_year(1900, 3, 1) == 60
    assert day_of_year(1900, 12, 31) == 365


def test_century_year_divisible_by_400_is_leap():
    # 2000 is a leap year (divisible by 400)
    assert day_of_year(2000, 2, 29) == 60
    assert day_of_year(2000, 3, 1) == 61
    assert day_of_year(2000, 12, 31) == 366


def test_leap_year_2100_not_leap():
    # 2100 is not a leap year (divisible by 100 but not 400)
    assert day_of_year(2100, 3, 1) == 60
    assert day_of_year(2100, 12, 31) == 365


def test_mid_year_date_non_leap():
    # June 15 in a non-leap year: 31+28+31+30+31+15 = 166
    assert day_of_year(2023, 6, 15) == 166


def test_mid_year_date_leap():
    # June 15 in a leap year: 31+29+31+30+31+15 = 167
    assert day_of_year(2024, 6, 15) == 167


def test_november_first_non_leap():
    # 31+28+31+30+31+30+31+31+30+31 = 304
    assert day_of_year(2023, 11, 1) == 305


def test_october_last_day_non_leap():
    # 31+28+31+30+31+30+31+31+30+31 = 304
    assert day_of_year(2023, 10, 31) == 304

