import pytest
from target import has_next_page


def test_exact_single_page_no_next():
    # Total items exactly fill one page -> no next page
    assert has_next_page(1, 10, 10) is False


def test_one_extra_item_has_next():
    # One item beyond a full page -> next page exists
    assert has_next_page(1, 10, 11) is True


def test_total_items_less_than_page_size():
    # Fewer items than page_size -> no next page
    assert has_next_page(1, 10, 5) is False


def test_zero_total_items():
    # No items at all -> no next page
    assert has_next_page(1, 10, 0) is False


def test_multi_page_boundary_no_next():
    # Exactly fills two pages -> no next page
    assert has_next_page(2, 10, 20) is False


def test_multi_page_boundary_has_next():
    # One item beyond two full pages -> next page exists
    assert has_next_page(2, 10, 21) is True


def test_page_size_one_no_next():
    # Single-item pages, exactly one item -> no next page
    assert has_next_page(1, 1, 1) is False


def test_page_size_one_has_next():
    # Single-item pages, two items -> next page exists
    assert has_next_page(1, 1, 2) is True


def test_last_page_of_uneven_total_no_next():
    # 25 items, page_size 10 -> pages: 10,10,5; page 3 is last, no next
    assert has_next_page(3, 10, 25) is False


def test_middle_page_of_uneven_total_has_next():
    # 25 items, page_size 10 -> page 2 still has a next page
    assert has_next_page(2, 10, 25) is True


def test_first_page_uneven_total_has_next():
    # 25 items, page_size 10 -> page 1 has a next page
    assert has_next_page(1, 10, 25) is True


def test_large_page_beyond_total_no_next():
    # Page far beyond total items -> no next page
    assert has_next_page(100, 10, 25) is False

