import pytest
from target import maxWeight


def test_four_basic():
    # sorted desc: [4,3,2,1], k=2
    # day1 (odd): eat 4 -> remaining {1,2,3}
    # day2 (even): largest remaining=3, second=2 -> eat 2
    # total = 4 + 2 = 6
    assert maxWeight([1, 2, 3, 4]) == 6


def test_four_reverse_order_input():
    # same multiset as above, given in different order
    assert maxWeight([4, 3, 2, 1]) == 6


def test_four_negative_values():
    # sorted desc: [-1,-2,-3,-4], k=2
    # day1: eat -1 -> remaining {-2,-3,-4}
    # day2: largest remaining=-2, second=-3 -> eat -3
    # total = -1 + -3 = -4
    assert maxWeight([-1, -2, -3, -4]) == -4


def test_four_floats():
    # sorted desc: [4.5, 3.5, 2.5, 1.5]
    # day1: eat 4.5 -> remaining {1.5,2.5,3.5}
    # day2: largest remaining=3.5, second=2.5 -> eat 2.5
    # total = 4.5 + 2.5 = 7.0
    assert maxWeight([1.5, 2.5, 3.5, 4.5]) == pytest.approx(7.0)


def test_eight_sequential():
    # sorted desc: [8,7,6,5,4,3,2,1], k=4
    # day1: eat 8 -> remaining {1,2,3,4,5,6,7}
    # day2: largest=7, second=6 -> eat 6 -> remaining {1,2,3,4,5,7}
    # day3: largest remaining=7 -> eat 7 -> remaining {1,2,3,4,5}
    # day4: largest=5, second=4 -> eat 4
    # total = 8 + 6 + 7 + 4 = 25
    assert maxWeight([1, 2, 3, 4, 5, 6, 7, 8]) == 25


def test_eight_unsorted_with_duplicates():
    # values sorted desc: [9,6,5,4,3,2,1,1]
